# planear, resolver problemas, escribir, reuniones y crecer en el trabajo).
# Cada unidad: palabras, frases con audio, diálogo, el error típico de quien habla español y un reto real.
from content_extra import h1, h3, p, ph, vo, tip, dlg

def reto(t): return {"t": "box", "kind": "tip", "title": "Reto de la semana", "items": [t]}

